"""Build a source-based offline document. This script does not mutate application data."""
from pathlib import Path
from datetime import datetime
import ast
import hashlib
import html
import json
import re

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'docs/CODE_WALKTHROUGH.html'
stamp = datetime.now().astimezone().isoformat(timespec='seconds')
def esc(value): return html.escape(str(value))
def code(value): return '<code>'+esc(value)+'</code>'
def src(rel, symbol=None):
    path=ROOT/rel
    content=path.read_text()
    line=None
    if symbol:
        if path.suffix=='.py':
            line=next((n.lineno for n in ast.walk(ast.parse(content)) if isinstance(n,(ast.FunctionDef,ast.ClassDef)) and n.name==symbol),None)
        else:
            line=next((i for i,s in enumerate(content.splitlines(),1) if re.search(r'\b(?:function|const)\s+'+re.escape(symbol)+r'\b',s)),None)
        if line is None: raise ValueError(f'Unresolved symbol: {rel}:{symbol}')
    label=rel+(f':{line} ({symbol})' if symbol else '')
    return f'<a class="source" href="../{esc(rel)}">{code(label)}</a>'
def table(headers,rows):
    return '<div class="scroll" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def pre(value): return '<pre><code>'+esc(value)+'</code></pre>'
def section(key,title,body):return f'<section id="{key}"><h2>{title}</h2>{body}</section>'
def para(s):return '<p>'+s+'</p>'

def sequence(key,lanes,messages):
    width=1060; xs=[90+i*220 for i in range(len(lanes))]; height=105+len(messages)*47
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {width} {height}" role="img" aria-labelledby="{key}-title"><title id="{key}-title">{esc(key.replace("-"," "))} request sequence</title><defs><marker id="{key}-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#526476"/></marker></defs>'
    for x,label in zip(xs,lanes):
        svg+=f'<text x="{x}" y="30" text-anchor="middle" font-size="15" font-weight="650">{esc(label)}</text><path d="M{x} 48 V{height-15}" stroke="#c6d0dc" stroke-dasharray="4 5"/>'
    for i,(a,b,label) in enumerate(messages):
        y=88+i*47;xa=xs[a];xb=xs[b]
        if a==b:
            direction=-1 if xa>800 else 1
            anchor='end' if direction<0 else 'start'
            svg+=f'<path d="M{xa} {y} h{65*direction} v20 h{-65*direction}" fill="none" stroke="#526476" marker-end="url(#{key}-arrow)"/><text x="{xa+75*direction}" y="{y+12}" text-anchor="{anchor}" font-size="12">{esc(label)}</text>'
        else:
            svg+=f'<path d="M{xa} {y} H{xb}" stroke="#526476" marker-end="url(#{key}-arrow)"/><text x="{(xa+xb)/2}" y="{y-9}" text-anchor="middle" font-size="12">{esc(label)}</text>'
    svg+='</svg>'
    return '<figure><div class="diagram">'+svg+'</div><figcaption>'+esc('Read top to bottom. Arrows identify the specific request and response steps. Database effects are described below.')+'</figcaption></figure>'

