api_body=para('Eight application endpoints are registered in '+src('backend/app/api/__init__.py')+' and mounted by '+src('backend/app/__init__.py','create_app')+'. All have <strong>no application authentication or authorization</strong>. Pydantic validation errors return 422. The shared unexpected-error handler returns a safe 500 body. Next.js page routes, static assets, and framework-generated OPTIONS/HEAD support are not business endpoints. Flask’s framework static route is not an application data API. No Swagger/OpenAPI-serving route is registered.')
api_body+=table(['Method and full path','Purpose / caller','Response and main branches'],[(f'<a href="#api-{e["key"]}">{code(e["method"]+" /api/v1"+e["path"])}</a>',e['caller'],e['response']) for e in endpoints])
api_body+=para('No frontend application call without a matching active backend route was found in the inspected pages/components. Health has no frontend caller. Outbound browser actions are website/GAF hyperlinks and tel links, not provider API calls. The maintained contract is '+src('openapi.yaml')+'; it supplies generated client types but does not generate Flask routes.')
api_body+='<h3>Shared error format</h3>'+pre('{"error":{"code":"validation_error","message":"The request is not valid.","details":{"fields":{"tier":"Input should be high, medium or low"}}}}')+para('This is a source-shaped abbreviated error example; exact observed messages retain quoted enum values. Handler: '+src('backend/app/errors.py','register_error_handlers')+'.')
api_body+='<h3>Request walkthroughs</h3>'+para('Expand each endpoint. Examples show selected fields to avoid copying full source data. GET examples are projections of observations from this review. POST and PATCH examples describe code paths and were not executed. Successful responses also contain the fields listed in the schema reference below.')
for e in endpoints:
    api_body+=f'<details id="api-{e["key"]}"><summary>{esc(e["method"]+" /api/v1"+e["path"])}</summary>'
    api_body+=para('<strong>Caller:</strong> '+esc(e['caller']))+para('<strong>Inputs:</strong> '+esc(e['inputs']))+para('<strong>Response:</strong> '+esc(e['response']))
    api_body+='<ol>'+''.join('<li><strong>'+esc(label)+':</strong> '+body+'</li>' for label,body in e['trace'])+'</ol>'
    api_body+=sequence('seq-'+e['key'],e['lanes'],e['arrows'])
    api_body+='<h4>Request and response projection</h4>'+pre(e['request'])+pre(e['example'])
    api_body+=para('<strong>Branches and limits:</strong> '+esc(e['branches']))+'</details>'
api_body+='<h3 id="schema-reference">Response schema reference</h3>'+table(['Schema','Returned fields'],[(src('backend/app/schemas.py',name),code(fields)) for name,fields in schemas.items()])
api_body+=para('Nested '+code('lead')+' is nullable and uses LeadInfo. '+code('also_listed_in')+' and '+code('saved_via')+' are nullable objects containing prospect_id and directory. Score breakdown uses ScoreItem[]. Numeric SQLAlchemy Decimal values are converted to float for JSON. Full nullability and types are defined in schemas.py and openapi.yaml; this review did not validate every runtime field against the full contract.')
sections.append(section('api','6. API inventory and endpoint-by-endpoint traces',api_body))

rules=[
('Distance / 35','None: 0 + unknown. ≤10 mi: 35. >10 to ≤25: 22. >25 to ≤50: 10. >50: 0. Conditions apply in this order.',src('backend/app/scoring.py','_geographic')),
('Certification / 20','Case-insensitive substring match. Top tier: 20, checked first. Otherwise certified tier: 12. Empty list: 0 + unknown. Other distinctions: known 0.',src('backend/app/scoring.py','_certification')),
('Roof systems / 10','Residential listing: 10. Commercial with any specialties: 10. Commercial without specialties: 0 + unknown.',src('backend/app/scoring.py','_roof_systems')),
('Specialty / 5','Any distinction/specialty containing fortified, metal, solar, or coating: 5. Otherwise 0, not flagged unknown by this subrule.',src('backend/app/scoring.py','_specialty')),
('Phone / 10','Nonempty phone field: 10. Otherwise 0 + unknown. Presence is distinct from a valid ten-digit company identity key.',src('backend/app/scoring.py','_readiness')),
('Website / 10','Nonempty website_url: 10. Otherwise 0 + unknown. This does not verify that the website is reachable.',src('backend/app/scoring.py','_readiness')),
('Address / 5','address, city and state all truthy: 5. Otherwise 0 + unknown.',src('backend/app/scoring.py','_readiness')),
('Freshness / 5','effective_time − retrieved_at ≤30 days: 5, else 0. Uses exact duration, not rounded displayed days. Current code also awards points for a future retrieved_at because it has no lower-bound age check.',src('backend/app/scoring.py','_readiness')),
]
sections.append(section('rules','7. Deterministic rules and a worked example',
    para('Score v1 sums these eight contributions in the order shown. It is a rule-based fit score, not a probability or sales prediction. '+code('tier_for')+' returns High for ≥70, Medium for 45–69, Low for &lt;45. Ratings, reviews, GAF result position, saved state, and AI output do not affect it. Scores are persisted during import/rescore rather than recalculated on every GET.')+
    table(['Rule / maximum','Exact current behavior','Implementation'],rules)+
    para('Top-tier match tokens: '+code("president's club, master elite, chairman's circle, platinumelite, platinum elite")+'. Certified tokens: '+code('certified, goldelite, gold elite, coatingspro')+'. These are substring rules over the original strings; they are not an independent certification verification service.')+
    '<h3>Worked recorded-data example</h3>'+para('The local API returned prospect 145, American Siding Construction Corp, in Newark NJ. Its GAF retrieval time was '+code('2026-11-05T19:06:09.333000Z')+' and stored scored_at was '+code('2026-11-05T19:23:22.471083Z')+'. The listing is residential, distance 6.5 miles, with a Master Elite distinction, a phone, website, and full address, but no scored specialty.')+
    pre('Distance 35 + certification 20 + residential systems 10 + specialty 0\n+ phone 10 + website 10 + full address 5 + freshness 5\n= 95 / 100 → High')+
    para('The API’s eight contribution values sum to 95 and agree with these conditions. This is one manually inspected recorded-data example, not a boundary test suite. Missing About text and Years in business remain unknown but do not contribute to this score.')+
    '<h3>Rules beyond scoring</h3>'+table(['Rule','Inputs → result / edge behavior','Evidence'],[
    ('Normalization','Collapse whitespace; trim strings; uppercase state; blank strings become None. Normalize phone to digits; remove leading US 1 from 11 digits; exactly ten digits become the company key; all other lengths become None.',src('backend/app/collection/importer.py','normalize')+'; '+src('backend/app/collection/importer.py','phone_digits')),
    ('Snapshot validation','Required IDs/names/timestamps; profile URL must start with https://www.gaf.com/. Invalid website scheme or rating outside 0–5 becomes None. Invalid record is reported; valid records continue. Validation is not full URL safety or timestamp/range validation.',src('backend/app/collection/snapshot.py','SnapshotRecord')),
    ('Import identity','Within one file, last record for a GAF source ID wins. Database identity is directory + GAF source ID. Upsert updates source fields only; does not delete absent listings or edit representative status. Completeness compares deduplicated valid count to expected_total and checks there are no invalid records.',src('backend/app/collection/importer.py','import_file')),
    ('Company matching','Same non-null ten-digit phone links listings across directories. A partial unique lead index prevents two saved leads with that key. It cannot distinguish companies sharing a phone or deduplicate two unknown-phone listings.',src('backend/app/queries.py','twins')+'; '+src('backend/app/models.py','Lead')),
    ('Prospect filtering','Search uses SQL ILIKE for name/city; % and _ have wildcard meaning. Directory/state/tier/distance/certification filters apply in SQL. hide_saved excludes directly saved rows and rows whose phone key is saved through another listing.',src('backend/app/queries.py','prospect_page')),
    ('Prospect ordering','Default: score descending, distance ascending with nulls last, name, id. Distance sort: distance, score descending, name, id. Name sort: name, id. Offset/limit apply to the SQL result.',src('backend/app/queries.py','_order')),
    ('Score reason','Keep positive contributions, sort by descending points then key, use the first three, and format a short reason. If none is positive, say No scoring signals found. Frontend chips split the reason string; they do not recalculate points.',src('backend/app/scoring.py','top_reason')+'; '+src('frontend/components/leads/ReasonChips.tsx','ReasonChips')),
    ('Lead scope and search','active excludes dismissed; all includes all; dismissed includes only dismissed. Queue/status/search/directory/tier further narrow the set. Lead search is a lowercase literal substring on name/city, unlike SQL ILIKE wildcard semantics for prospects.',src('backend/app/services.py','list_leads')),
    ('Lead ordering','priority = score descending, name, lead_id. recently_saved = saved_at descending, lead_id. oldest_status_change = timestamp ascending, lead_id. Apply ordering before page slicing. A tie-breaker stabilizes an unchanged dataset; live edits can still shift offset pages.',src('backend/app/services.py')+' (LEAD_SORTS)'),
    ('Statuses / follow-up','Allowed statuses: new, contacted, qualified, dismissed. Any transition is allowed. Repeating the same status does not reset its timestamp. Follow-up due = contacted AND unchanged for ≥14 days, based on one UTC now per service call.',src('backend/app/services.py','update_status')+'; '+src('backend/app/services.py','is_follow_up_due')),
    ])+
    para('Determinism requires the same source fields, rule version, and effective time. '+code('flask rescore')+' uses current UTC time, so freshness points can change. GET does not automatically refresh an old stored score. Displayed times use America/New_York, while comparisons use UTC durations. A status timestamp is not an actual call-history timestamp.')))

sections.append(section('ui','8. Frontend behavior and dashboard metrics',
    table(['Page','Data and visible responsibilities','State / limits'],[
     ('Overview /','GET overview; saved counts, pipeline snapshot, Call next, Follow up, top unsaved. Mark contacted sends the status mutation.', 'Local load callback and component state. The Contacted KPI includes Qualified, but its link filters only status=contacted. This is a static semantic mismatch when qualified leads exist.'),
     ('Prospects /prospects','GET prospects plus separate GET stats; URL filters/sorting, source timestamp, priority mix, directories, distance chart, save action.', 'Global stats do not follow list filters. A distance-band chart can apply a cumulative max-distance filter rather than an exclusive band, so labels need care. max_distance currently fails runtime validation.'),
     ('Prospect details /prospects/[id]','GET detail; GAF facts, about text, scoring, unknowns, external source links; save or status control.', 'No provider enrichment or notes. Missing data stays visibly unknown; current source code cannot infer purchase volume, supplier, crew size, pipeline, or decision-maker.'),
     ('Saved leads /leads','GET leads; call queues, all-saved status counts, matching total, filters, sorting, reasons/distance, inline status and contact actions.', 'Global card counts precede filters. Desktop table and narrow-screen compact list share actions. Each action has row-level feedback. State is refreshed after mutation, not persisted in browser storage.'),
    ])+
    '<h3>Exact KPI semantics</h3>'+table(['Metric','Calculation / population','Interpretation'],[
     ('Overview.saved','All leads except dismissed.','Active saved leads, not all-time saves.'),
     ('Overview.not_contacted','Count status=new.','Current New status; no independent proof of contact history.'),
     ('Overview.contacted','Count contacted + qualified.','Contacted-or-qualified population.'),
     ('Overview.contacted_pct','round(100 × (contacted + qualified) / active saved); 0 if active is empty.','Current-state coverage, not historical conversion.'),
     ('Overview.qualified','Count status=qualified.','Current qualification state, not won accounts or revenue.'),
     ('LeadList.status_counts / queue_counts / total_saved','Counts across all saved leads before current table filters.','Global navigation counts. total is the matching count before pagination.'),
     ('Needs first contact','queue_counts.first_contact = status new.','Action queue based on status.'),
     ('Follow-up due','queue_counts.follow_up_due = contacted unchanged ≥14 days.','Duration since status change, not a scheduled task or logged last call.'),
     ('ProspectStats.high_unsaved','Scored prospects ≥70 not saved directly or through known company key.','Counts listing candidates; unknown/shared phones limit company-level identity.'),
    ])+
    '<h3>Loading, cancellation, and errors</h3>'+para(src('frontend/lib/useLoad.ts','useLoad')+' stores data/error/loading, increments a sequence on each run, aborts effect-owned requests on cleanup, and ignores outcomes from older runs when a newer sequence exists. It retains prior data on refresh/error. This supports a stable UI but does not establish that every navigation race is solved; manual reload controllers are not managed identically to effect-owned ones.')+
    para('SaveButton disables duplicate clicks and shows a local error. StatusSelect temporarily updates its selection, disables while pending, and restores the prior selection on failure. Saved-lead status cells use a key containing lead/status to remount when refreshed status changes. ContactActions stores per-row feedback. None of these operations includes a general automatic retry loop.')+
    para('Accessibility affordances include visible labels, named selects, native buttons and tables, aria-pressed filter controls, aria-sort on sortable prospect headings, role=alert errors, and polite live status. These are source-observed affordances; keyboard, contrast, screen-reader, and breakpoint behavior were not verified in this review.')))

sections.append(section('recovery','9. Writes, partial failures, and recovery',
    table(['Operation / failure','What remains saved','User-visible result / recovery','Limit'],[
     ('Read fails or older response arrives','Database unaffected. React can retain previous records.','Alert/retry, prior list while refresh runs; useLoad guards request sequences.','Overview uses its own loading pattern; browser race checks remain outstanding.'),
     ('Save unique-key collision','Only the winning committed lead remains. Losing transaction rolls back.','Same prospect is intended to return existing detail/200; different matching listing yields 409 and alternate prospect information.','Known-phone identity only. Concurrent race behavior was not exercised here.'),
     ('Save commits, response fails','The lead may exist despite a client error.','Reload or retry the same prospect; uniqueness/idempotent handling should avoid a second lead.','No durable request-id ledger. Not all integrity errors are distinguished.'),
     ('Status request fails','If validation fails, nothing changes. A lost response can occur after a commit.','Select restores old display; row shows error. Reload reconciles with database.','No edit version, status-history record, or merge policy; concurrent writers can overwrite.'),
     ('Import succeeds, rescore fails','import_file commits prospect upserts before rescore_all commits scores. Earlier files may also be committed.','CLI reports errors; operator can rerun import/rescore after resolving the failure.','The entire multi-file import plus scoring is not one atomic transaction. A new prospect without a score may be omitted from lists or break detail access.'),
     ('Restart / data volume loss','Ordinary restart should preserve named pgdata. Volume removal removes database contents.','Reimport can restore source facts, but cannot recreate lost representative status from JSON alone.','No backup/restore implementation or independent restart-persistence check in this review.'),
    ])+
    para('Source: '+src('backend/app/collection/importer.py','import_file')+' commits before '+src('backend/app/collection/importer.py','rescore_all')+'; '+src('backend/app/db.py','session_scope')+' cannot roll back work already committed inside those helpers. A short import-file module comment still mentions lead_insights although that active table has been removed. The schema and imports are the authoritative evidence.')))

decisions=[
('D1/D3: one-time snapshot import','Recorded rationale: ordinary HTTP was blocked, while browser collection worked; user selected one-time storage and wider territory. Active code reads JSON instead of searching GAF.','Live scraping increases operational and access risk; an approved feed is a future alternative. Browser-access claims are historical log evidence, not reverified here.','collection/snapshot.py, importer.py, cli.py; new source adapter and compatibility validation when an approved feed exists.'),
('D4: three ownership groups','Recorded rationale: separate GAF facts, calculated score, and representative work. Current models match the revised three-table decision.','One wide table is simpler to query but mixes update ownership. More contact/note/history tables add complexity absent current requirements.','models.py, queries/services, schema initialization; revisit for per-rep lead ownership and history.'),
('D7: fixed score','Recorded rationale: explainability and no score changes from saving. Current code uses no AI or ratings in the calculation.','An LLM rank is harder to reproduce; learned weighting needs outcome data rather than intuition alone.','scoring.py, import/rescore, UI explanations; version rules and validate against outcomes before changing meaning.'),
('D8: phone company identity','Recorded rationale: avoid saving the same company through two directories. Partial unique index is the enforcement boundary.','Separate saves permit duplicates; an authoritative company ID is stronger but absent.','Phone normalization, lead index, twin lookup, save handling; revisit shared/missing phone behavior or a stable company ID.'),
('D5: create_all, no Alembic','Recorded rationale: migrations excluded from MVP. Advisory lock serializes worker initialization.','Versioned migrations cost setup but support controlled schema evolution. create_all does not modify existing columns.','db.py/models.py and deployment procedure; revisit before schema change must preserve saved data.'),
('D15: same-origin forwarding','Recorded rationale: one browser origin and no separate CORS setup. Inference: keeps browser client configuration small.','Direct cross-origin API calls require intentional origin/authentication configuration.','next.config.mjs, lib/api.ts, deployment URLs; revisit if API serves a separate domain/consumer.'),
('D10/D11: defer notes and insight','Recorded rationale: user removed them from MVP. additional/insights is disconnected draft.','Adding them now expands schema, UI, external dependencies, and failure paths.','Future feature needs fresh approval, integration validation, data protection, and source/claim policy.'),
('D6/D17: test constraints','Recorded choices: no fictional fixtures, no separate test database, no automated tests until requested.','Isolated fixtures/databases simplify repeatability and boundary coverage but conflict with current choices.','Future test setup must preserve existing rows, clean only its own writes, and report unavailable cases. No current test coverage is inferred from dependency files.'),
]
sections.append(section('decisions','10. Design decisions and trade-offs',para('Decision IDs refer to '+src('docs/DECISION_LOG.md')+'. Approved here means the log records approval; the earlier approval conversation was not independently reviewed. Inferences are marked. Alternatives are comparisons unless the log explicitly records them.')+table(['Choice','Why / evidence','Alternative and limit','Affected code / revisit trigger'],decisions)))

sections.append(section('production','11. Production evolution — proposals',
    para('These are proposed changes, not implemented features or permission to expand scope. Expected traffic, SLOs, recovery objectives, sales impact, and capacity are unknown.')+
    table(['Priority / trigger','Current limitation','Proposed change and affected boundary'],[
     ('Before shared/external use','No login, roles, or per-rep ownership. Database and API host ports are published by Compose.','Define users/access rules, authentication/authorization, appropriate network exposure, TLS, and secret handling. Affects models, API guards, frontend session, and deployment.'),
     ('Before treating filters/contracts as reliable','Valid max_distance request fails. Complete runtime contract agreement has not been checked.','Resolve input coercion and verify success/null/error responses against Pydantic/OpenAPI and the generated client. Affects schemas, API callers, contract, verification.'),
     ('Before changing a schema containing important data','create_all cannot migrate an existing schema; no tested backup/restore process.','Add a reviewed schema-upgrade and rollback plan plus backup/restore checks. Migration tooling is a scope change. Affects db.py, models, operating procedures.'),
     ('Before recurring imports or refreshed scoring matters','Manual snapshots age; score freshness becomes stale until explicit rescore; import and scoring commit separately.','Define collection rights, source refresh schedule, stale-data display, atomic/recoverable ingest, and score-version policy. Affects collection, CLI, models, detail/query behavior.'),
     ('Before concurrent representatives edit leads','Last-writer-wins status with no version/history. Phone is imperfect company identity.','Define conflict handling, ownership, and company matching policy; add version checks/history only when approved. Affects Lead, save/status services, callers.'),
     ('Before operational commitments','Basic logs/health only. No load evidence, request metrics, alerting, or restore proof.','Add operation-focused logs and metrics, request identifiers, error/latency monitoring, health/readiness separation, and ownership. Affects app factory, error handler, deployment/operations.'),
     ('When saved leads exceed the bounded-MVP assumption','all_leads loads all rows before filter/sort/page; stats makes multiple queries.','Measure rows/query latency first. Move saved-lead filtering/counting/pagination into SQL and add indexes justified by query plans. Cache only if measurements justify invalidation complexity.'),
     ('Only if notes/AI/CRM are requested','Disconnected insight draft is untested; no notes or integration workflow.','Approve feature/data contracts and failure/retry rules first. Validate provider results and credentials. Durable background jobs may fit slow work, but queues are not an automatic upgrade.'),
    ])+
    para('No production-readiness or extensibility handoff file existed under docs/operations at inspection. Do not treat links to absent handoff files in other documentation as completed operational work.')))

